spec=importlib.util.spec_from_file_location('sp',str(pathlib.Path(__file__).with_name('review_special_brace.py')));sp=importlib.util.module_from_spec(spec);spec.loader.exec_module(sp)
INDEX=pathlib.Path('.bench-work/commercial-246/yjk-calibration-2/selected-native-evidence-v3/yjk-state-evidence-index.json');ROOT=INDEX.parent;OUT=pathlib.Path(__file__).with_name('rigidity-representation-review.json')
